DO $$ BEGIN
  CREATE POLICY "Public can update approvals for in-progress meetings"
ON public.presentation_creative_approvals
FOR UPDATE
USING (
  meeting_id IN (
    SELECT pm.id FROM public.presentation_meetings pm
