-- =============================================
-- CRM Restructure: Separar Lead de Negócio (Deal)
-- =============================================

-- 1. Criar tabela de CONTATOS (os leads/clientes)
CREATE TABLE IF NOT EXISTS public.crm_contacts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id UUID NOT NULL REFERENCES crm_workspaces(id) ON DELETE CASCADE,
  
  -- Dados de identificação
  full_name TEXT NOT NULL,
  email TEXT,
  phone TEXT,
  company_name TEXT,
  
  -- Redes sociais e web
  facebook TEXT,
  instagram TEXT,
  website TEXT,
  
  -- Localização
  city TEXT,
  state TEXT,
  country TEXT,
  
  -- Rastreamento/Origem
  external_id TEXT,
  utm_source TEXT,
  utm_medium TEXT,
  utm_campaign TEXT,
  utm_term TEXT,
  utm_content TEXT,
  
  -- Metadados
  notes TEXT,
  tags TEXT[],
  custom_fields JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID REFERENCES auth.users(id),
  
  -- Constraint para evitar duplicatas no mesmo workspace
  CONSTRAINT crm_contacts_workspace_external_id_unique UNIQUE (workspace_id, external_id)
);;

-- 2. Criar tabela de NEGÓCIOS (deals/oportunidades)
CREATE TABLE IF NOT EXISTS public.crm_deals (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id UUID NOT NULL REFERENCES crm_workspaces(id) ON DELETE CASCADE,
  contact_id UUID NOT NULL REFERENCES crm_contacts(id) ON DELETE CASCADE,
  stage_id UUID NOT NULL REFERENCES crm_stages(id) ON DELETE RESTRICT,
  
  -- Dados do negócio
  title TEXT NOT NULL,
  value NUMERIC,
  quantity INTEGER DEFAULT 1,
  
  -- Status e temperatura
  status TEXT DEFAULT 'open' CHECK (status IN ('open', 'won', 'lost')),
  temperature TEXT CHECK (temperature IN ('cold', 'warm', 'hot')),
  
  -- Datas
  start_date TIMESTAMPTZ DEFAULT NOW(),
  expected_close_date TIMESTAMPTZ,
  closed_at TIMESTAMPTZ,
  
  -- Responsabilidade
  responsible_id UUID REFERENCES auth.users(id),
  
  -- Notas e desqualificação
  notes TEXT,
  disqualification_reason TEXT,
  
  -- Workflow e links
  workflow_id TEXT,
  source_deal_id UUID REFERENCES crm_deals(id),
  
  -- Arquivamento
  is_archived BOOLEAN DEFAULT FALSE,
  archived_at TIMESTAMPTZ,
  
  -- Metadados
  custom_fields JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID REFERENCES auth.users(id)
);;

-- 3. Criar tabela de ATIVIDADES do negócio
CREATE TABLE IF NOT EXISTS public.crm_deal_activities (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  deal_id UUID NOT NULL REFERENCES crm_deals(id) ON DELETE CASCADE,
  contact_id UUID REFERENCES crm_contacts(id) ON DELETE CASCADE,
  
  -- Tipo e descrição
  activity_type TEXT NOT NULL,
  notes TEXT,
  
  -- Stages para mudanças
  from_stage_id UUID REFERENCES crm_stages(id),
  to_stage_id UUID REFERENCES crm_stages(id),
  
  -- Valores antigos/novos para logs de mudança
  old_value TEXT,
  new_value TEXT,
  
  -- Metadados
  metadata JSONB DEFAULT '{}',
  is_manual BOOLEAN DEFAULT FALSE,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID REFERENCES auth.users(id)
);;

-- 4. Criar tabela de LINKS entre negócios (para workflow)
CREATE TABLE IF NOT EXISTS public.crm_deal_links (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  source_deal_id UUID NOT NULL REFERENCES crm_deals(id) ON DELETE CASCADE,
  target_deal_id UUID NOT NULL REFERENCES crm_deals(id) ON DELETE CASCADE,
  link_type TEXT NOT NULL DEFAULT 'workflow',
  created_at TIMESTAMPTZ DEFAULT NOW(),
  
  CONSTRAINT crm_deal_links_unique UNIQUE (source_deal_id, target_deal_id)
);;

-- 5. Índices para performance
CREATE INDEX IF NOT EXISTS idx_crm_contacts_workspace ON crm_contacts(workspace_id);;

CREATE INDEX IF NOT EXISTS idx_crm_contacts_email ON crm_contacts(email);;

CREATE INDEX IF NOT EXISTS idx_crm_contacts_phone ON crm_contacts(phone);;

CREATE INDEX IF NOT EXISTS idx_crm_contacts_external_id ON crm_contacts(external_id);;

CREATE INDEX IF NOT EXISTS idx_crm_deals_workspace ON crm_deals(workspace_id);;

CREATE INDEX IF NOT EXISTS idx_crm_deals_contact ON crm_deals(contact_id);;

CREATE INDEX IF NOT EXISTS idx_crm_deals_stage ON crm_deals(stage_id);;

CREATE INDEX IF NOT EXISTS idx_crm_deals_status ON crm_deals(status);;

CREATE INDEX IF NOT EXISTS idx_crm_deals_archived ON crm_deals(is_archived);;

CREATE INDEX IF NOT EXISTS idx_crm_deal_activities_deal ON crm_deal_activities(deal_id);;

CREATE INDEX IF NOT EXISTS idx_crm_deal_activities_contact ON crm_deal_activities(contact_id);;

DROP TRIGGER IF EXISTS update_crm_contacts_updated_at ON crm_contacts;
CREATE TRIGGER update_crm_contacts_updated_at
  BEFORE UPDATE ON crm_contacts
  FOR EACH ROW
  EXECUTE FUNCTION public.update_updated_at_column();

DROP TRIGGER IF EXISTS update_crm_deals_updated_at ON crm_deals;
CREATE TRIGGER update_crm_deals_updated_at
  BEFORE UPDATE ON crm_deals
  FOR EACH ROW
  EXECUTE FUNCTION public.update_updated_at_column();



