  l.utm_media,
  l.utm_campaign,
  l.notes,
  l.created_at,
  l.updated_at
FROM crm_leads l
WHERE l.external_id IS NOT NULL
ON CONFLICT (workspace_id, external_id) DO NOTHING;


-- Criar contatos para leads sem external_id (usar id do lead como external_id)
INSERT INTO crm_contacts (
  workspace_id,
  full_name,
  email,
  phone,
  company_name,
  facebook,
  instagram,
  website,
  city,
  state,
  external_id,
  utm_source,
  utm_medium,
  utm_campaign,
  notes,
  created_at,
  updated_at
)
SELECT 
  l.workspace_id,
  l.full_name,
  l.email,
  l.phone,
  l.company_name,
  l.facebook,
  l.instagram,
  l.website,
  l.city,
  l.state,
  l.id::TEXT as external_id,
  l.utm_source,
  l.utm_media,
  l.utm_campaign,
  l.notes,
  l.created_at,
  l.updated_at
FROM crm_leads l
WHERE l.external_id IS NULL
ON CONFLICT (workspace_id, external_id) DO NOTHING;


-- Depois, criar deals a partir dos leads existentes
INSERT INTO crm_deals (
  workspace_id,
  contact_id,
  stage_id,
  title,
  value,
  quantity,
  status,
  temperature,
  start_date,
  expected_close_date,
  responsible_id,
  notes,
  disqualification_reason,
  workflow_id,
  is_archived,
  created_at,
  updated_at
)
SELECT 
  l.workspace_id,
  c.id as contact_id,
  l.stage_id,
  COALESCE(l.full_name, 'Negócio') as title,
  l.value,
  l.quantity,
  CASE 
    WHEN l.status = 'ganho' THEN 'won'
    WHEN l.status = 'perdido' THEN 'lost'
    ELSE 'open'
  END as status,
  l.temperature,
  l.start_date,
  l.expected_close_date,
  l.responsible_id,
  l.notes,
  l.disqualification_reason,
  l.workflow_id,
  COALESCE(l.is_archived, false),
  l.created_at,
  l.updated_at
FROM crm_leads l
JOIN crm_contacts c ON c.workspace_id = l.workspace_id 
  AND c.external_id = COALESCE(l.external_id, l.id::TEXT);


-- 13. Migrar atividades existentes para a nova tabela
INSERT INTO crm_deal_activities (
  deal_id,
  activity_type,
  notes,
  from_stage_id,
  to_stage_id,
  is_manual,
  created_at,
  created_by
)
SELECT 
  d.id as deal_id,
  a.activity_type,
  a.notes,
  a.from_stage_id,
  a.to_stage_id,
  COALESCE(a.is_manual, false),
  a.created_at,
  a.created_by
FROM crm_lead_activities a
JOIN crm_leads l ON l.id = a.lead_id
JOIN crm_contacts c ON c.workspace_id = l.workspace_id 
  AND c.external_id = COALESCE(l.external_id, l.id::TEXT)
JOIN crm_deals d ON d.contact_id = c.id AND d.workspace_id = l.workspace_id;


