-- >>> Migration: 20251228221413_6f741426-0b8e-4407-8dfd-08e15c201f48.sql <<<
-- Create a secure RPC to set a company's TV dashboard token
-- This avoids RLS update issues while still enforcing authorization.

CREATE OR REPLACE FUNCTION public.set_tv_dashboard_token(p_company_id uuid, p_token text)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF p_company_id IS NULL OR p_token IS NULL OR length(p_token) = 0 THEN
    RAISE EXCEPTION 'invalid input';

  END IF;


  -- Only company owner/admin can set the token
  IF NOT public.is_company_admin_or_owner(auth.uid(), p_company_id) THEN
    RAISE EXCEPTION 'not authorized';

  END IF;


  UPDATE public.companies
  SET tv_dashboard_token = p_token,
      updated_at = now()
  WHERE id = p_company_id;


  IF NOT FOUND THEN
    RAISE EXCEPTION 'company not found';

  END IF;

END;

$$;


-- >>> Migration: 20251228221720_6e21068c-cd02-4e98-a7fc-8c29ec98be4a.sql <<<
-- Simplify the function to allow any company member to set the token
CREATE OR REPLACE FUNCTION public.set_tv_dashboard_token(p_company_id uuid, p_token text)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF p_company_id IS NULL OR p_token IS NULL OR length(p_token) = 0 THEN
    RAISE EXCEPTION 'invalid input';

  END IF;


  -- Check if user is any member of the company
  IF NOT EXISTS (
    SELECT 1 FROM public.company_members 
    WHERE user_id = auth.uid() AND company_id = p_company_id
  ) THEN
    RAISE EXCEPTION 'not authorized';

  END IF;


  UPDATE public.companies
  SET tv_dashboard_token = p_token,
      updated_at = now()
  WHERE id = p_company_id;


  IF NOT FOUND THEN
    RAISE EXCEPTION 'company not found';

  END IF;

END;

$$;


-- >>> Migration: 20251228221807_23092cc4-49ee-4c01-a930-4e530d1dc54a.sql <<<
-- Update function to also check if user is the company creator
CREATE OR REPLACE FUNCTION public.set_tv_dashboard_token(p_company_id uuid, p_token text)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF p_company_id IS NULL OR p_token IS NULL OR length(p_token) = 0 THEN
    RAISE EXCEPTION 'invalid input';

  END IF;


  -- Check if user is member of the company OR the creator
  IF NOT EXISTS (
    SELECT 1 FROM public.company_members 
    WHERE user_id = auth.uid() AND company_id = p_company_id
  ) AND NOT EXISTS (
    SELECT 1 FROM public.companies 
    WHERE id = p_company_id AND created_by = auth.uid()
  ) THEN
    RAISE EXCEPTION 'not authorized';

  END IF;


  UPDATE public.companies
  SET tv_dashboard_token = p_token,
      updated_at = now()
  WHERE id = p_company_id;


  IF NOT FOUND THEN
    RAISE EXCEPTION 'company not found';

  END IF;

END;

$$;


