-- Função para registrar atividade automaticamente
CREATE OR REPLACE FUNCTION public.log_activity(
  p_company_id UUID,
  p_user_id UUID,
  p_activity_type TEXT,
  p_entity_type TEXT,
  p_entity_id UUID,
  p_title TEXT,
  p_description TEXT DEFAULT NULL,
  p_metadata JSONB DEFAULT '{}'
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_activity_id UUID;

BEGIN
  INSERT INTO activity_feed (
    company_id,
    user_id,
    activity_type,
    entity_type,
    entity_id,
    title,
    description,
    metadata
  ) VALUES (
    p_company_id,
    p_user_id,
    p_activity_type,
    p_entity_type,
    p_entity_id,
    p_title,
    p_description,
    p_metadata
  )
  RETURNING id INTO v_activity_id;

  
  RETURN v_activity_id;

END;

$$;


