  USING (
    created_by = auth.uid() OR
    company_id IN (
      SELECT company_id FROM public.company_members 
      WHERE user_id = auth.uid() AND role = 'admin'
    )
  );
EXCEPTION WHEN duplicate_object OR duplicate_table THEN null;
END $$;


