-- ==========================================
-- YouTube Content Lab - Database Structure
-- ==========================================

-- 1. Canais monitorados do YouTube
CREATE TABLE IF NOT EXISTS public.youtube_monitored_channels (
  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  client_id UUID NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE,
  company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,
  channel_id TEXT NOT NULL,
  channel_url TEXT NOT NULL,
  channel_name TEXT NOT NULL,
  channel_handle TEXT,
  thumbnail_url TEXT,
  subscriber_count BIGINT,
  video_count BIGINT,
  is_active BOOLEAN NOT NULL DEFAULT true,
  last_analyzed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID REFERENCES auth.users(id),
  UNIQUE(client_id, channel_id)
);;

-- 2. Cache de análises de vídeos
CREATE TABLE IF NOT EXISTS public.youtube_video_analyses (
  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  channel_id UUID NOT NULL REFERENCES public.youtube_monitored_channels(id) ON DELETE CASCADE,
  client_id UUID NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE,
  company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,
  video_id TEXT NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  thumbnail_url TEXT,
  published_at TIMESTAMPTZ NOT NULL,
  view_count BIGINT NOT NULL DEFAULT 0,
  like_count BIGINT NOT NULL DEFAULT 0,
  comment_count BIGINT NOT NULL DEFAULT 0,
  duration_seconds INTEGER,
  engagement_rate NUMERIC(10, 4),
  analyzed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  ai_theme_analysis TEXT,
  ai_summary TEXT,
  UNIQUE(channel_id, video_id)
);;

-- 3. Sugestões de conteúdo geradas pela IA
CREATE TABLE IF NOT EXISTS public.youtube_content_suggestions (
  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  client_id UUID NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE,
  company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  description TEXT,
  based_on_videos JSONB DEFAULT '[]'::jsonb,
  theme_category TEXT,
  estimated_engagement TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'selected', 'scripted', 'completed', 'dismissed')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);;

-- 4. Roteiros de vídeos
CREATE TABLE IF NOT EXISTS public.youtube_scripts (
  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  client_id UUID NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE,
  company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,
  suggestion_id UUID REFERENCES public.youtube_content_suggestions(id) ON DELETE SET NULL,
  title TEXT NOT NULL,
  script_content TEXT NOT NULL DEFAULT '',
  suggested_titles JSONB DEFAULT '[]'::jsonb,
  thumbnail_url TEXT,
  reference_thumbnails JSONB DEFAULT '[]'::jsonb,
  video_duration_target INTEGER,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'review', 'approved', 'produced')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID REFERENCES auth.users(id)
);;

-- 5. Mensagens do chat de refinamento
CREATE TABLE IF NOT EXISTS public.youtube_script_messages (
  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  script_id UUID NOT NULL REFERENCES public.youtube_scripts(id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK (role IN ('user', 'assistant')),
  content TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);;

-- Indexes para performance
CREATE INDEX IF NOT EXISTS idx_youtube_channels_client ON public.youtube_monitored_channels(client_id);;

CREATE INDEX IF NOT EXISTS idx_youtube_channels_company ON public.youtube_monitored_channels(company_id);;

CREATE INDEX IF NOT EXISTS idx_youtube_videos_channel ON public.youtube_video_analyses(channel_id);;

CREATE INDEX IF NOT EXISTS idx_youtube_videos_published ON public.youtube_video_analyses(published_at DESC);;

CREATE INDEX IF NOT EXISTS idx_youtube_videos_engagement ON public.youtube_video_analyses(engagement_rate DESC NULLS LAST);;

CREATE INDEX IF NOT EXISTS idx_youtube_suggestions_client ON public.youtube_content_suggestions(client_id);;

CREATE INDEX IF NOT EXISTS idx_youtube_scripts_client ON public.youtube_scripts(client_id);;

CREATE INDEX IF NOT EXISTS idx_youtube_messages_script ON public.youtube_script_messages(script_id);;



-- Habilitar RLS
