ALTER TABLE public.youtube_video_analyses ENABLE ROW LEVEL SECURITY;

ALTER TABLE public.youtube_content_suggestions ENABLE ROW LEVEL SECURITY;

ALTER TABLE public.youtube_scripts ENABLE ROW LEVEL SECURITY;

