    SELECT 1 FROM public.internal_channels ic
    WHERE ic.id = channel_id
    AND public.is_company_member(auth.uid(), ic.company_id)
  )
);
EXCEPTION WHEN duplicate_object OR duplicate_table THEN null;
END $$;

