  END IF;


  request_body := jsonb_build_object(
    'message_id', NEW.id,
    'channel_id', NEW.channel_id,
    'user_id', NEW.user_id,
    'content', NEW.content
  );


  headers := jsonb_build_object(
    'Content-Type', 'application/json',
