-- >>> Migration: 20260317120000_fix_workspace_shares_insert_policy.sql <<<
-- Fix: colaboradores não-admin não conseguem compartilhar suas próprias notas
-- Causa: policy INSERT em workspace_shares faz sub-query em workspace_documents
-- que por sua vez tem RLS referenciando workspace_shares (dependência circular)
-- Solução: função SECURITY DEFINER que bypassa RLS para verificar ownership

CREATE OR REPLACE FUNCTION public.user_owns_workspace_resource(
  _resource_type TEXT,
  _resource_id UUID,
  _user_id UUID
) RETURNS BOOLEAN
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM workspace_documents
    WHERE id = _resource_id AND created_by = _user_id AND _resource_type = 'document'
    UNION ALL
    SELECT 1 FROM workspace_folders
    WHERE id = _resource_id AND created_by = _user_id AND _resource_type = 'folder'
  );

$$;


-- Drop old policy
DROP POLICY IF EXISTS "Users can create shares for owned resources" ON public.workspace_shares;
DO $$ BEGIN
  CREATE POLICY "Users can create shares for owned resources"
ON public.workspace_shares FOR INSERT
WITH CHECK (
  shared_by = auth.uid()
  AND user_owns_workspace_resource(resource_type, resource_id, auth.uid())
);
EXCEPTION WHEN duplicate_object OR duplicate_table THEN null;
END $$;


-- >>> Migration: 20260317150000_add_resolve_board_owners_function.sql <<<
-- Function to resolve board column user_ids to employee names
-- Needed because employee.user_id may differ from auth.uid() used to create columns
-- This SECURITY DEFINER function can access auth.users to match by email
CREATE OR REPLACE FUNCTION public.resolve_board_owner_names(
  _company_id UUID
)
RETURNS TABLE(auth_uid UUID, employee_name TEXT)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT DISTINCT
    tbc.user_id AS auth_uid,
    COALESCE(
      -- First try: direct employee match by user_id
      (SELECT e.name FROM employees e
       WHERE e.user_id = tbc.user_id AND e.company_id = _company_id AND e.status = 'active'
       LIMIT 1),
      -- Second try: match via auth.users email → employee email
      (SELECT e.name FROM auth.users au
       JOIN employees e ON lower(e.email) = lower(au.email)
         AND e.company_id = _company_id AND e.status = 'active'
       WHERE au.id = tbc.user_id
       LIMIT 1),
      -- Third try: profile full_name
      (SELECT p.full_name FROM profiles p WHERE p.user_id = tbc.user_id),
      'Desconhecido'
    ) AS employee_name
  FROM task_board_columns tbc
  WHERE tbc.company_id = _company_id;

$$;


