-- --------------------------------------------------------
-- 3) Trigger updated_at
-- --------------------------------------------------------
CREATE OR REPLACE FUNCTION public.touch_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

DO $$
DECLARE t TEXT;
BEGIN
  FOR t IN SELECT unnest(ARRAY[
    'system_config_app',
    'system_config_facebook',
    'system_config_google',
    'system_config_ai',
    'system_config_email',
    'system_config_tools',
    'system_config_discord',
    'system_config_github'
  ])
  LOOP
    EXECUTE format(
      'DROP TRIGGER IF EXISTS %I ON public.%I;', t || '_touch', t
    );
    EXECUTE format(
      'CREATE TRIGGER %I BEFORE UPDATE ON public.%I
       FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();',
      t || '_touch', t
    );
  END LOOP;
END $$;

-- --------------------------------------------------------
-- 4) RLS — somente system_owner
-- --------------------------------------------------------
DO $$
DECLARE t TEXT;
BEGIN
  FOR t IN SELECT unnest(ARRAY[
    'system_config_app',
    'system_config_facebook',
    'system_config_google',
    'system_config_ai',
    'system_config_email',
    'system_config_tools',
    'system_config_discord',
    'system_config_github'
  ])
  LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY;', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I;', 'owner_all_' || t, t);
    EXECUTE format(
      'CREATE POLICY %I ON public.%I
       FOR ALL
       TO authenticated
       USING (public.is_system_owner())
       WITH CHECK (public.is_system_owner());',
      'owner_all_' || t, t
    );
  END LOOP;
END $$;

-- --------------------------------------------------------
-- 5) GRANT
-- --------------------------------------------------------
DO $$
DECLARE t TEXT;
BEGIN
  FOR t IN SELECT unnest(ARRAY[
    'system_config_app',
    'system_config_facebook',
    'system_config_google',
    'system_config_ai',
    'system_config_email',
    'system_config_tools',
    'system_config_discord',
    'system_config_github'
  ])
  LOOP
    EXECUTE format(
      'GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated;', t
    );
  END LOOP;
END $$;

